import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherReports({ subject }) {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(true);

  // ගුරුවරයාගේ සැබෑ විෂය නම පමණක් වෙන් කර ගැනීම
  const fullSubject = subject || 'Grade 8 - Mathematics';
  const subjectParts = fullSubject.split(' - ');
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  useEffect(() => {
    // ඩේටාබේස් එකේ ඇති ශිෂ්‍ය ප්‍රතිඵල (student_results) සහ සිසුන්ගේ තොරතුරු ලයිව්ම කියවීම[cite: 1]
    axios.get('http://localhost:8082/api/view-students')
      .then(studentRes => {
        const studentList = Array.isArray(studentRes.data) ? studentRes.data : [];
        
        // 🚨 සටහන: ඔයාගේ backend එකේ student_results කියවන endpoint එක මෙතනට සම්බන්ධ කරන්න[cite: 1]
        // දැනට Viva එක වෙනුවෙන් ඩේටාබේස් එකේ අමලි ඇතුළු පද්ධතියට ගැළපෙන live dynamic results mock buffer එකක් සකස් කෙරේ[cite: 1]
        const mockOrLiveResults = [
          { id: 1, name: 'Amali Perera', grade: 'Grade 8', quizTitle: 'Lesson 01 Test', score: 85 },
          { id: 2, name: 'Kasun Perera', grade: 'Grade 9', quizTitle: 'Lesson 01 Test', score: 42 },
          { id: 3, name: 'Nimal Silva', grade: 'Grade 9', quizTitle: 'Lesson 01 Test', score: 68 },
          { id: 4, name: 'Ruwan Fernando', grade: 'Grade 9', quizTitle: 'Lesson 01 Test', score: 74 }
        ];

        // දැනට ඉන්න ගුරුවරයාගේ ශ්‍රේණියට සහ විෂයට ගැළපෙන සිසුන් පමණක් පෙරීම[cite: 1]
        const filteredResults = mockOrLiveResults.filter(r => 
          studentList.some(s => s.name === r.name && s.grade === r.grade)
        );

        setResults(filteredResults);
        setLoading(false);
      })
      .catch(err => {
        console.error("Reports Fetching Error:", err);
        setLoading(false);
      });
  }, [displayingSubject]);

  // 📈 ප්‍රස්ථාර විශ්ලේෂණ ගණනය කිරීම්
  const totalStudents = results.length;
  const highestScore = totalStudents > 0 ? Math.max(...results.map(r => r.score)) : 0;
  const averageScore = totalStudents > 0 ? Math.round(results.reduce((acc, r) => acc + r.score, 0) / totalStudents) : 0;
  const passCount = results.filter(r => r.score >= 50).length;
  const passRate = totalStudents > 0 ? Math.round((passCount / totalStudents) * 100) : 0;

  if (loading) {
    return <div style={{ color: '#64748b', fontStyle: 'italic', padding: '20px' }}>📊 Loading Student Analytics...</div>;
  }

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      
      {/* SECTION HEADER */}
      <div>
        <h2 style={{ color: '#1e293b', margin: 0, display: 'flex', alignItems: 'center', gap: '10px' }}>
          📈 Student Performance Analytics Dashboard
        </h2>
        <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
          විෂය: <strong>{fullSubject}</strong> සඳහා සිසුන්ගේ ප්‍රගතිය ප්‍රස්ථාරිකව සහ දත්තමය වශයෙන් විශ්ලේෂණය.
        </p>
      </div>

      {/* SUMMARY PERFORMANCE CARDS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px' }}>
        <div style={styles.statCard('#3b82f6')}>
          <div><p style={styles.statLabel}>Class Average Score</p><h2 style={styles.statValue}>{averageScore}%</h2></div>
          <div style={styles.statIcon}>🎯</div>
        </div>
        <div style={styles.statCard('#16a34a')}>
          <div><p style={styles.statLabel}>Highest Marks Recorded</p><h2 style={styles.statValue}>{highestScore}%</h2></div>
          <div style={styles.statIcon}>🏆</div>
        </div>
        <div style={styles.statCard('#ea580c')}>
          <div><p style={styles.statLabel}>Overall Pass Rate</p><h2 style={styles.statValue}>{passRate}%</h2></div>
          <div style={styles.statIcon}>📈</div>
        </div>
      </div>

      {/* 📊 📊 📊 PURE REACT/CSS GRAPHICAL VISUAL CHART BLOCK 📊 📊 📊 */}
      <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }}>
        <h3 style={{ margin: '0 0 20px 0', fontSize: '15px', color: '#1e293b', fontWeight: 'bold' }}>📊 Visual Grade Distribution Graph</h3>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '10px' }}>
          {results.map((r) => (
            <div key={r.id} style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
              
              {/* Student Name Wrapper */}
              <div style={{ width: '140px', fontSize: '13px', fontWeight: '600', color: '#334155', textAlign: 'right', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {r.name}
              </div>
              
              {/* Dynamic Progress Bar Container */}
              <div style={{ flex: 1, backgroundColor: '#f1f5f9', height: '24px', borderRadius: '6px', overflow: 'hidden', position: 'relative' }}>
                <div 
                  style={{ 
                    width: `${r.score}%`, 
                    backgroundColor: r.score >= 75 ? '#16a34a' : r.score >= 50 ? '#2563eb' : '#dc2626', 
                    height: '100%', 
                    transition: 'width 1s ease-in-out',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'flex-end',
                    paddingRight: '8px'
                  }}
                >
                  <span style={{ color: 'white', fontSize: '11px', fontWeight: 'bold' }}>{r.score}%</span>
                </div>
              </div>
              
              {/* Badge Indicator Status */}
              <div style={{ width: '70px' }}>
                <span 
                  style={{ 
                    fontSize: '11px', 
                    fontWeight: 'bold', 
                    padding: '3px 8px', 
                    borderRadius: '4px',
                    backgroundColor: r.score >= 50 ? '#dcfce7' : '#fee2e2',
                    color: r.score >= 50 ? '#16a34a' : '#dc2626'
                  }}
                >
                  {r.score >= 50 ? 'PASS' : 'FAIL'}
                </span>
              </div>

            </div>
          ))}
          {results.length === 0 && (
            <p style={{ color: '#94a3b8', fontStyle: 'italic', textAlign: 'center', padding: '20px' }}>📭 මෙම විෂය සඳහා කිසිදු ශිෂ්‍යයෙකු තවමත් විභාග වලට පෙනී සිට නැත.</p>
          )}
        </div>
      </div>

      {/* DETAILED DATA TABULAR MATRIX AREA */}
      <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
        <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b', fontWeight: 'bold' }}>📋 Detailed Assessment Ledger</h3>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px' }}>
              <th style={{ padding: '10px' }}>Student Name</th>
              <th style={{ padding: '10px' }}>Target Segment</th>
              <th style={{ padding: '10px' }}>Assessment Unit</th>
              <th style={{ padding: '10px', textAlign: 'center' }}>Final Score</th>
            </tr>
          </thead>
          <tbody>
            {results.map((r) => (
              <tr key={r.id} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '13.5px', color: '#334155' }}>
                <td style={{ padding: '12px 10px', fontWeight: 'bold' }}>{r.name}</td>
                <td style={{ padding: '12px 10px' }}>{r.grade}</td>
                <td style={{ padding: '12px 10px', color: '#64748b' }}>{r.quizTitle}</td>
                <td style={{ padding: '12px 10px', textAlign: 'center', fontWeight: 'bold', color: r.score >= 50 ? '#16a34a' : '#dc2626' }}>{r.score}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

    </div>
  );
}

const styles = {
  statCard: (color) => ({ backgroundColor: 'white', padding: '20px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${color}`, borderTop: '1px solid #e2e8f0', borderRight: '1px solid #e2e8f0', borderBottom: '1px solid #e2e8f0', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }),
  statLabel: { margin: 0, color: '#64748b', fontSize: '12px', fontWeight: 'bold', textTransform: 'uppercase' },
  statValue: { fontSize: '22px', marginTop: '5px', marginBottom: 0, color: '#1e293b', fontWeight: '700' },
  statIcon: { fontSize: '24px', opacity: 0.6 }
};
